#include <LiquidCrystal_I2C.h>
#include <Keypad.h>

LiquidCrystal_I2C lcd(0x20, 16, 2);

#define buzzer   10
#define reset    A0
#define ledR     11
#define ledY     9
#define bombPin  13          // сюда подаётся напряжение ТОЛЬКО при взрыве

const byte ROWS = 4;
const byte COLS = 3;
char keys[ROWS][COLS] = {
  {'1','2','3'},
  {'4','5','6'},
  {'7','8','9'},
  {'*','0','#'}
};
byte rowPins[ROWS] = {2,3,4,5};
byte colPins[COLS] = {6,7,8};
Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);

char password[8];
char masterKey[8] = "7355608";
byte indicator = 0;

// ---------- СОСТОЯНИЯ ----------
bool bombArmed = false;      // пароль введён верно
bool exploded  = false;      // взрыв уже произошёл

// ---------- ТАЙМЕР ДО ВЗРЫВА ----------
const unsigned long FUSE_MS = 30000UL;   // 30 секунд до взрыва после взведения
unsigned long armTime = 0;

// ---------- ПИЩАЛКА ----------
unsigned long lastBeep   = 0;
int  beepInterval = 1000;
int  beepCount    = 0;
const int BEEP_STEPS = 40;

// ---------- СООБЩЕНИЕ ОБ ОШИБКЕ ----------
unsigned long errorUntil = 0;

// ============================================================
// ВЗРЫВ
// ============================================================
void explode() {
  if (exploded) return;
  exploded  = true;
  bombArmed = false;

  digitalWrite(bombPin, HIGH);      // <-- НАПРЯЖЕНИЕ НА 13 ТОЛЬКО ЗДЕСЬ
  digitalWrite(ledR, HIGH);
  digitalWrite(ledY, LOW);
  tone(buzzer, 800, 1000);

  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("BOMB DETONATED");
  lcd.setCursor(0, 1);
  lcd.print("PIN 13 = HIGH");

  Serial.println("BOOM! pin 13 HIGH");
}

// ============================================================
// ПОЛНЫЙ СБРОС ИГРЫ
// ============================================================
void resetGame() {
  lcd.clear();
  lcd.setCursor(5, 0);

  indicator = 0;
  exploded  = false;
  bombArmed = false;

  digitalWrite(bombPin, LOW);
  digitalWrite(ledR, LOW);
  digitalWrite(ledY, HIGH);
  noTone(buzzer);

  beepCount    = 0;
  beepInterval = 1000;
  errorUntil   = 0;

  // очистить буфер пароля
  for (byte i = 0; i < 8; i++) password[i] = 0;
}

// ============================================================
// SETUP
// ============================================================
void setup() {
  Serial.begin(9600);

  lcd.begin(16, 2);
  lcd.init();
  lcd.setBacklight(1);
  lcd.setCursor(5, 0);

  pinMode(buzzer,  OUTPUT);
  pinMode(ledR,    OUTPUT);
  pinMode(ledY,    OUTPUT);
  pinMode(bombPin, OUTPUT);
  pinMode(reset,   INPUT_PULLUP);   // кнопка на GND, подтяжка встроенная

  digitalWrite(bombPin, LOW);       // при старте напряжения нет
  digitalWrite(ledY, HIGH);
}

// ============================================================
// LOOP
// ============================================================
void loop() {
  unsigned long now = millis();

  // ---------- КНОПКА СБРОСА (работает ВСЕГДА) ----------
  if (digitalRead(reset) == LOW) {   // LOW = нажата (PULLUP)
    delay(30);                       // антидребезг
    if (digitalRead(reset) == LOW) {
      resetGame();
      while (digitalRead(reset) == LOW) { /* ждём отпускания */ }
    }
  }

  // ---------- ВВОД ПАРОЛЯ ----------
  char key = keypad.getKey();
  if (key) Serial.println(key);      // отладка: видно нажатия в Serial

  if (key && !bombArmed && !exploded && indicator < 7 && errorUntil == 0) {
    password[indicator] = key;
    indicator++;
    lcd.print(key);
  }

  // ---------- ЖЁЛТЫЙ LED ----------
  if (!bombArmed && !exploded) digitalWrite(ledY, HIGH);

  // ---------- ПРОВЕРКА ПАРОЛЯ ----------
  if (indicator == 7 && !bombArmed && !exploded) {
    if (!strcmp(password, masterKey)) {
      Serial.println("correct");
      lcd.clear();
      lcd.setCursor(0, 0);
      lcd.print("BOMB ARMED");
      digitalWrite(ledY, LOW);

      bombArmed    = true;
      armTime      = now;
      beepCount    = 0;
      beepInterval = 1000;
      lastBeep     = now - beepInterval;   // первый писк сразу
    } else {
      Serial.println("incorrect");
      lcd.clear();
      lcd.print("incorrect");
      errorUntil = now + 2000;             // 2 сек — неблокирующее сообщение
      indicator  = 0;
    }
  }

  // ---------- СНЯТИЕ СООБЩЕНИЯ ОБ ОШИБКЕ ----------
  if (errorUntil && now > errorUntil) {
    errorUntil = 0;
    lcd.clear();
    lcd.setCursor(5, 0);
  }

  // ---------- ЛОГИКА ВЗВЕДЁННОЙ БОМБЫ ----------
  if (bombArmed && !exploded) {

    // Вариант A: истёк общий таймер
    if (now - armTime >= FUSE_MS) {
      explode();
    }
    // Вариант B: пищалка дошла до конца
    else if (beepCount >= BEEP_STEPS) {
      explode();
    }
    // Пищалка (неблокирующая)
    else if (now - lastBeep >= (unsigned long)beepInterval) {
      lastBeep = now;

      tone(buzzer, 800, 100);
      digitalWrite(ledR, HIGH);

      beepCount++;
      beepInterval = 1000 - beepCount * 25;
      if (beepInterval < 25) beepInterval = 25;
    }
    else {
      // гасим красный между писками
      digitalWrite(ledR, LOW);
    }
  }
}
